package com.coffeeshop.service;import com.coffeeshop.dto.SettingCommands;import com.coffeeshop.model.SettingModels;import com.coffeeshop.repository.SettingRepository;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;class SettingServiceTest{private final Stub repo=new Stub();private final SettingService service=new SettingService(repo);@Test void validatesAndNormalizes(){service.save(new SettingCommands.Save(null," test.key "," 12.50 ","decimal"," Test ",null),1);assertEquals("test.key",repo.saved.key());assertEquals("DECIMAL",repo.saved.type());assertEquals("12.50",repo.saved.value());}@Test void validatesTypedValues(){assertThrows(IllegalArgumentException.class,()->save("INTEGER","1.5"));assertThrows(IllegalArgumentException.class,()->save("BOOLEAN","yes"));assertThrows(IllegalArgumentException.class,()->save("DECIMAL","money"));}@Test void rejectsCredentialSettings(){assertThrows(IllegalArgumentException.class,()->service.save(new SettingCommands.Save(null,"database.password","value","STRING",null,null),1));}@Test void updateRequiresVersion(){assertThrows(IllegalArgumentException.class,()->service.save(new SettingCommands.Save(1L,"key","value","STRING",null,null),1));}@Test void requiresAuthenticatedAdministrator(){assertThrows(IllegalArgumentException.class,()->service.save(new SettingCommands.Save(null,"key","value","STRING",null,null),0));}private void save(String t,String v){service.save(new SettingCommands.Save(null,"key",v,t,null,null),1);}private static final class Stub implements SettingRepository{SettingCommands.Save saved;public List<SettingModels.Setting>find(String s){return List.of();}public long save(SettingCommands.Save q,long u){saved=q;return 1;}}}
